-- GameXS editorial overviews, part 9 (ps5_games.overview, migration 040).
--
-- Same format and rules as db/content/game_overviews.sql: original Persian copy
-- written for GameXS; no text was copied. Facts checked against the IGDB data
-- stored in ps5_games. Rows whose IGDB data describes a different product than
-- the shops sell are skipped and listed in db/content/catalog_mismatches_part9.md.
--
-- Shape: {"intro", "suits": [..], "sections": [{"heading", "paragraphs": [..], "media"}]}
-- media = "trailer" | "screenshot:N" (1-based index into screenshot_ids); a key
-- the game has no asset for is skipped at render time.
--
-- Idempotent: re-running overwrites the overview of each listed slug and
-- touches nothing else. Apply with:
--   docker exec -i gamexs-postgres psql -U gamexs -d gamexs -v ON_ERROR_STOP=1 < db/content/game_overviews_part9.sql

UPDATE ps5_games g
SET overview = v.overview::jsonb
FROM (VALUES
('mortal-kombat-11-ultimate', $j${
  "intro": "Mortal Kombat 11 Ultimate کامل‌ترین نسخه یازدهمین شماره سری مبارزه‌ای خشن و مشهور Mortal Kombat است که استودیو NetherRealm آن را ساخته و Warner Bros. منتشر کرده است. این بسته بازی اصلی، بسته داستانی Aftermath و همه شخصیت‌های اضافه‌شده بعد از عرضه را یکجا در اختیار شما می‌گذارد؛ یعنی فهرستی ۳۷ نفره از مبارزان که شخصیت‌هایی مثل Rain، Mileena و حتی Rambo را هم شامل می‌شود.",
  "suits": ["طرفداران بازی‌های مبارزه‌ای", "بازی رودررو با دوستان", "علاقه‌مندان داستان‌های سینمایی"],
  "sections": [
    {
      "heading": "داستان: جنگ با زمان",
      "paragraphs": [
        "در داستان اصلی، کرونیکا، نگهبان زمان، تصمیم گرفته تاریخ را به عقب برگرداند و همه‌چیز را از نو بسازد. نتیجه این است که نسخه‌های جوان و پیر شخصیت‌ها کنار هم قرار می‌گیرند و مبارزان سرزمین زمین باید با گذشته خودشان هم روبه‌رو شوند. این ایده به NetherRealm اجازه داده دوستی‌ها و دشمنی‌های قدیمی سری را با زاویه‌ای تازه نشان دهد.",
        "بسته Aftermath ادامه همین ماجراست و داستان را از جایی که بازی اصلی تمام می‌شود پی می‌گیرد. هر دو کمپین به سبک فیلم‌های اکشن روایت می‌شوند و میان‌پرده‌های طولانی و باکیفیتی دارند؛ برای همین حتی کسانی که اهل رقابت جدی نیستند هم از تمام کردن آن‌ها لذت می‌برند."
      ],
      "media": "screenshot:1"
    },
    {
      "heading": "مبارزه و شخصی‌سازی",
      "paragraphs": [
        "سیستم مبارزه MK11 نسبت به نسخه قبل کمی کندتر و حساب‌شده‌تر است. ضربه‌های Fatal Blow وقتی جان شما کم شده فرصت برگشت به مبارزه را می‌دهند و Krushing Blowها با یک حرکت درست، ضربه‌ای سینمایی و پرقدرت می‌سازند. فیتالیتی‌ها و براتالیتی‌های معروف سری هم با جزئیات کامل حضور دارند.",
        "هر شخصیت چند لباس، ابزار و مجموعه حرکت قابل‌تنظیم دارد و می‌توانید نسخه دلخواه خودتان را از هر مبارز بسازید. بخش Krypt، جزیره‌ای پر از صندوق و راز، محل باز کردن بخش بزرگی از این آیتم‌هاست."
      ],
      "media": "screenshot:3"
    },
    {
      "heading": "حالت‌های تک‌نفره و آنلاین",
      "paragraphs": [
        "کنار داستان، برج‌های کلاسیک با پایان اختصاصی برای هر شخصیت، بخش آموزش بسیار کامل و مبارزه محلی دونفره با یک کنسول در دسترس است. برج‌های زمان (Towers of Time) و بخش‌های رقابتی رتبه‌بندی‌شده اما به اتصال به سرور وابسته‌اند و تجربه کامل آن‌ها بدون اینترنت ممکن نیست."
      ],
      "media": "screenshot:5"
    },
    {
      "heading": "کدام نوع خرید مناسب‌تر است؟",
      "paragraphs": [
        "اگر بیشتر داستان، برج‌های کلاسیک و مبارزه دونفره کنار دوستتان را می‌خواهید، اکانت ظرفیت ۱ ارزان‌ترین انتخاب است، به شرط این‌که کنسول بعد از نصب آفلاین بماند. اگر قصد مبارزه آنلاین و استفاده از بخش‌های وابسته به سرور را دارید، ظرفیت ۲ یا ۳ را انتخاب کنید و در نظر داشته باشید که بازی آنلاین روی PS5 معمولاً به اشتراک PS Plus نیاز دارد. ظرفیت ۲ آزادی بیشتری در آنلاین و آفلاین بودن می‌دهد. قیمت هر روش، از جمله دیسک، را در جدول همین صفحه مقایسه کنید."
      ]
    }
  ]
}$j$),
('dynasty-warriors-origins', $j${
  "intro": "Dynasty Warriors Origins تازه‌ترین شماره سری اکشن تاریخی Dynasty Warriors است که استودیو Omega Force ساخته و Koei Tecmo در ژانویه ۲۰۲۵ منتشر کرده است. این بار به‌جای انتخاب از میان ده‌ها ژنرال مشهور، در نقش قهرمانی بی‌نام وارد دوران آشوب‌زده سه پادشاهی چین می‌شوید و با همان فرمول آشنای «یک نفر در برابر هزار نفر»، اما با جزئیات و مقیاسی بسیار بزرگ‌تر، میدان‌های نبرد را زیر و رو می‌کنید.",
  "suits": ["طرفداران اکشن هک‌اند‌اسلش", "علاقه‌مندان تاریخ چین", "بازیکنان تک‌نفره"],
  "sections": [
    {
      "heading": "بازگشت به ریشه‌ها",
      "paragraphs": [
        "Origins تمرکز را روی یک شخصیت اصلی گذاشته است؛ جنگجویی گمنام که در دوران شورش دستارزردها و جنگ‌های پس از آن، کنار چهره‌هایی مثل کائو کائو، لیو بی و خاندان سون قرار می‌گیرد. این ساختار باعث شده داستان منسجم‌تر و شخصی‌تر از نسخه‌های قبلی روایت شود و رابطه قهرمان با شخصیت‌های تاریخی معنای بیشتری پیدا کند.",
        "در بخش‌هایی از داستان می‌توانید تصمیم بگیرید کنار کدام جناح بجنگید و همین انتخاب‌ها مسیر و نبردهای بعدی شما را شکل می‌دهند."
      ],
      "media": "screenshot:1"
    },
    {
      "heading": "میدان نبرد واقعاً شلوغ است",
      "paragraphs": [
        "بزرگ‌ترین تغییر این نسخه تعداد سربازان روی صفحه است. ارتش‌ها به‌شکل توده‌هایی عظیم با هم برخورد می‌کنند و حس یک جنگ واقعی را می‌سازند. مبارزه هم عمیق‌تر شده است؛ دفع ضربه، جاخالی و حرکت‌های ویژه سلاح اهمیت بیشتری دارند و مبارزه با افسران دشمن بیشتر شبیه دوئل است تا دکمه‌کوبی.",
        "قهرمان می‌تواند بین چند نوع سلاح جابه‌جا شود و هر کدام سبک حرکت و ضربه‌های ویژه خودش را دارد. فرمان دادن به همراهان و استفاده از حمله‌های گروهی هم در لحظه‌های حساس نبرد را به سود شما تغییر می‌دهد."
      ],
      "media": "screenshot:3"
    },
    {
      "heading": "برای چه کسی مناسب است؟",
      "paragraphs": [
        "اگر از دیدن صدها دشمن که با هر ضربه به هوا پرتاب می‌شوند لذت می‌برید، Origins دقیقاً همان چیزی است که می‌خواهید. برای تازه‌واردها هم نقطه شروع خوبی است، چون داستان از ابتدای دوران سه پادشاهی شروع می‌شود و نیازی به آشنایی با نسخه‌های قبلی ندارد."
      ],
      "media": "screenshot:5"
    },
    {
      "heading": "کدام نوع خرید مناسب‌تر است؟",
      "paragraphs": [
        "Dynasty Warriors Origins بازی‌ای کاملاً تک‌نفره است، پس اکانت ظرفیت ۱ ارزان‌ترین گزینه است، به شرط این‌که کنسول بعد از نصب آفلاین بماند. اگر می‌خواهید کنسول همیشه به اینترنت وصل باشد یا بازی‌های آنلاین دیگری هم دارید، ظرفیت ۲ انعطاف بیشتری می‌دهد. قیمت اکانت‌ها و دیسک را در جدول همین صفحه مقایسه کنید."
      ]
    }
  ]
}$j$),
('nba-2k25', $j${
  "intro": "NBA 2K25 نسخه سال ۲۰۲۵ پرفروش‌ترین سری شبیه‌ساز بسکتبال است که استودیو Visual Concepts ساخته و 2K در سپتامبر ۲۰۲۴ منتشر کرده است. موتور حرکتی ProPLAY که حرکت‌های واقعی بازیکنان NBA را مستقیماً به بازی منتقل می‌کند، در این نسخه گسترده‌تر شده و مجموعه همیشگی حالت‌ها، از MyCAREER تا MyTEAM و MyNBA و لیگ زنان The W، دوباره حاضرند.",
  "suits": ["طرفداران بسکتبال و NBA", "بازیکنان رقابتی آنلاین", "علاقه‌مندان مدیریت تیم"],
  "sections": [
    {
      "heading": "حس بسکتبال واقعی",
      "paragraphs": [
        "ProPLAY ویدیوهای مسابقات واقعی را به انیمیشن تبدیل می‌کند تا دریبل، شوت و حرکت بدون توپ هر ستاره شبیه نسخه واقعی‌اش باشد. کنترل‌ها هم دقیق‌تر شده‌اند و بازیکنان باتجربه می‌توانند با ترکیب حرکت‌های دریبل و شوت‌های زمان‌بندی‌شده، سبک بازی خودشان را پیاده کنند. پخش تلویزیونی، گزارشگری و فضای سالن‌ها هم مثل همیشه از نقاط قوت سری هستند."
      ]
    },
    {
      "heading": "حالت‌های اصلی",
      "paragraphs": [
        "در MyCAREER بازیکن خودتان را می‌سازید و از تازه‌کار تا ستاره لیگ بالا می‌برید؛ این بخش روی PS5 در شهری آنلاین به نام The City جریان دارد که محل دیدار و رقابت با بازیکنان دیگر است. MyTEAM حالت جمع‌آوری کارت و ساخت تیم رؤیایی از ستاره‌های امروز و دیروز است.",
        "اگر اهل مدیریت هستید، MyNBA به شما اجازه می‌دهد یک باشگاه را سال‌ها اداره کنید یا حتی تاریخ لیگ را از دوره‌های قدیمی‌تر بازنویسی کنید. The W هم همین تجربه را برای لیگ زنان WNBA فراهم می‌کند."
      ]
    },
    {
      "heading": "نکته‌ای درباره ارز درون‌بازی",
      "paragraphs": [
        "پیشرفت در MyCAREER و MyTEAM به ارز درون‌بازی VC وابسته است که هم با بازی کردن و هم با خرید به دست می‌آید. اگر قصد ندارید پول اضافه خرج کنید، بدانید ارتقای بازیکن در این بخش‌ها زمان زیادی می‌برد؛ اما حالت‌های آفلاین مثل MyNBA و Play Now بدون این دغدغه قابل‌بازی هستند."
      ]
    },
    {
      "heading": "کدام نوع خرید مناسب‌تر است؟",
      "paragraphs": [
        "بخش بزرگی از جذابیت NBA 2K25، یعنی The City و MyTEAM، آنلاین است؛ برای همین اکانت ظرفیت ۱ که فقط آفلاین کار می‌کند انتخاب مناسبی نیست، مگر این‌که فقط MyNBA و مسابقه سریع بخواهید. برای تجربه کامل ظرفیت ۲ یا ۳ را انتخاب کنید و در نظر داشته باشید که بازی آنلاین روی PS5 معمولاً به PS Plus نیاز دارد. قیمت‌ها را در جدول همین صفحه مقایسه کنید."
      ]
    }
  ]
}$j$),
('outriders-complete-edition', $j${
  "intro": "Outriders یک شوتر نقش‌آفرینی علمی‌تخیلی از استودیو لهستانی People Can Fly است که Square Enix در سال ۲۰۲۱ منتشر کرد. بازی را می‌توانید تنها یا با حداکثر دو همراه آنلاین تمام کنید و ترکیب تیراندازی سوم‌شخص با قدرت‌های ماورایی، آن را از شوترهای پوشش‌محور معمولی متمایز می‌کند. نسخه Complete Edition علاوه بر بازی اصلی، بسته بزرگ Worldslayer را هم دارد.",
  "suits": ["علاقه‌مندان شوتر نقش‌آفرینی", "بازی همکاری با دوستان", "طرفداران جمع‌آوری غنیمت"],
  "sections": [
    {
      "heading": "سیاره‌ای که نباید خانه می‌شد",
      "paragraphs": [
        "بشریت پس از نابودی زمین به سیاره انوک رسیده است، اما طوفانی مرموز به نام آنومالی همه‌چیز را به هم می‌ریزد. شخصیت شما، یکی از Outriderها یا پیشگامان مهاجرت، در این طوفان قدرت‌هایی غیرعادی به دست می‌آورد و سال‌ها بعد در دنیایی بیدار می‌شود که به جنگ داخلی و هرج‌ومرج کشیده شده است. سفر برای پیدا کردن منبع یک سیگنال مرموز، شما را از شهرهای حلبی‌آباد تا جنگل‌ها، کوهستان‌ها و صحراهای انوک می‌برد."
      ],
      "media": "screenshot:1"
    },
    {
      "heading": "چهار کلاس، چهار سبک بازی",
      "paragraphs": [
        "Outriders چهار کلاس دارد: Devastator که در خط مقدم مقاومت می‌کند، Pyromancer که با آتش دشمنان را می‌سوزاند، Trickster که با جابه‌جایی زمان و مکان از پشت ضربه می‌زند و Technomancer که با ابزار و برجک از دور پشتیبانی می‌کند. نکته جالب این است که سلامتی شما با کشتن دشمنان برمی‌گردد، پس بازی شما را به جلو رفتن و حمله تهاجمی تشویق می‌کند، نه پنهان شدن پشت دیوار.",
        "سلاح‌ها و زره‌ها مدام بهتر می‌شوند و سیستم ساخت‌وساز اجازه می‌دهد قابلیت‌های آن‌ها را تغییر دهید تا با درخت مهارت کلاس شما هماهنگ شوند."
      ],
      "media": "screenshot:4"
    },
    {
      "heading": "Worldslayer و محتوای پایانی",
      "paragraphs": [
        "بسته Worldslayer داستان را ادامه می‌دهد و سیستم‌های تازه‌ای برای پیشرفت شخصیت در محتوای پایانی اضافه می‌کند؛ از جمله درخت مهارت جدید و یک سیاه‌چال تکرارشونده که برای کسانی که دنبال بهترین تجهیزات هستند ساخته شده است."
      ],
      "media": "screenshot:7"
    },
    {
      "heading": "کدام نوع خرید مناسب‌تر است؟",
      "paragraphs": [
        "Outriders حتی در حالت تک‌نفره به اتصال اینترنت نیاز دارد، پس اکانت ظرفیت ۱ که باید آفلاین بماند برای این بازی مناسب نیست. ظرفیت ۲ یا ۳ را انتخاب کنید؛ برای بازی همکاری آنلاین با دوستان هم در نظر داشته باشید که بازی آنلاین روی PS5 معمولاً به PS Plus نیاز دارد. قیمت هر روش را در جدول همین صفحه مقایسه کنید."
      ]
    }
  ]
}$j$),
('skull-and-bones', $j${
  "intro": "Skull And Bones بازی نقش‌آفرینی اکشن دریایی و آنلاین Ubisoft است که توسط Ubisoft Singapore ساخته شد و در فوریه ۲۰۲۴ منتشر شد. شما ناخدای یک کشتی دزدان دریایی هستید که از صفر شروع می‌کند و با غارت، تجارت و نبردهای دریایی به یکی از ترسناک‌ترین سرکرده‌های اقیانوس تبدیل می‌شود. بازی به‌صورت سرویس فصلی اداره می‌شود و با هر فصل رویداد و محتوای تازه دریافت می‌کند.",
  "suits": ["طرفداران نبرد دریایی", "بازیکنان آنلاین و گروهی", "علاقه‌مندان دنیای دزدان دریایی"],
  "sections": [
    {
      "heading": "قلمرو دزدان دریایی",
      "paragraphs": [
        "ماجرا در اقیانوس هند و در دوره طلایی دزدی دریایی می‌گذرد؛ منطقه‌ای پر از مسیرهای تجاری پرسود که امپراتوری‌های استعماری بر آن چنگ انداخته‌اند. بعد از غرق شدن کشتی‌تان، با یک قایق کوچک شروع می‌کنید و کم‌کم شهرت، خدمه و ناوگانی قوی‌تر به دست می‌آورید.",
        "تمرکز اصلی بازی روی خود کشتی است، نه مبارزه پیاده. بیشتر وقت شما پشت سکان می‌گذرد و پیاده‌روی در بندرها بیشتر برای تجارت، گرفتن مأموریت و ساخت‌وساز است."
      ],
      "media": "screenshot:1"
    },
    {
      "heading": "ساخت کشتی و نبرد دریایی",
      "paragraphs": [
        "می‌توانید انواع کشتی بسازید و هر کدام را با توپ، خمپاره، آتش‌افکن، زره و تزئینات دلخواه تجهیز کنید. نبردها به جهت باد، زاویه شلیک و مدیریت آسیب بستگی دارند و در پایان، پهلو گرفتن و حمله به کشتی دشمن غنیمت اصلی را به شما می‌دهد.",
        "بخش دیگری از پیشرفت، ساختن امپراتوری تجاری و تولید کالاهای قاچاق است که درآمد ثابت برایتان فراهم می‌کند و به شما اجازه می‌دهد قوی‌ترین تجهیزات را بخرید."
      ],
      "media": "screenshot:4"
