('sniper-ghost-warrior-contracts-2', $j${
  "intro": "Sniper Ghost Warrior Contracts 2 شوتر تاکتیکی و مخفی‌کارانه استودیو لهستانی CI Games است که در سال ۲۰۲۱ منتشر شد. شما در نقش «ریوِن»، تک‌تیراندازی که برای قرارداد می‌جنگد، به کشوری خیالی در خاورمیانه فرستاده می‌شوید تا اهدافی مهم را حذف کنید. تمرکز اصلی بازی روی شلیک‌های بسیار دوربرد است؛ شلیک‌هایی که در آن‌ها باد، فاصله و سقوط گلوله تعیین می‌کنند هدف را می‌زنید یا لو می‌روید.",
