('unravel-two', $j${
  "intro": "Unravel Two دنباله بازی پلتفرمر و معمایی Unravel است که استودیو سوئدی ColdWood Interactive ساخته و Electronic Arts در سال ۲۰۱۸ منتشر کرد. این بار به‌جای یک عروسک کاموایی، دو «یارنی» دارید که با یک نخ به هم بسته شده‌اند. بازی را می‌توانید تنها و با جابه‌جایی بین دو شخصیت انجام دهید یا با یک دوست کنار هم روی یک کنسول تجربه کنید. این بازی نسخه PS4 است و روی PS5 هم اجرا می‌شود.",
