('brothers-a-tale-of-two-sons-remake', $j${
  "intro": "Brothers A Tale Of Two Sons Remake بازسازی یکی از به‌یادماندنی‌ترین بازی‌های ماجرایی مستقل است که اولین بار در سال ۲۰۱۳ با کارگردانی یوزف فارس منتشر شد. این نسخه را استودیو AvantGarden با موتور Unreal Engine 5 بازسازی کرده و 505 Games در فوریه ۲۰۲۴ منتشر کرده است. داستان دو برادر که برای نجات پدرشان راهی سفری خطرناک می‌شوند، با گرافیکی تازه دوباره روایت شده است.",
  "suits": ["علاقه‌مندان داستان‌های احساسی", "بازی دونفره کنار هم", "بازیکنان کم‌وقت"],
  "sections": [
    {
      "heading": "سفری برای آب زندگی",
