('football-manager-2024', $j${
  "intro": "Football Manager 2024 نسخه کنسولی شبیه‌ساز مشهور مدیریت فوتبال Sports Interactive است که Sega در نوامبر ۲۰۲۳ منتشر کرد. اینجا خبری از کنترل مستقیم بازیکنان نیست؛ شما سرمربی و مدیر یک باشگاه هستید و باید با تاکتیک، نقل‌وانتقالات، تمرین و مدیریت رختکن، تیمتان را به افتخار برسانید. نسخه کنسولی، تجربه نسخه کامپیوتری را برای دسته بازی ساده‌تر و روان‌تر کرده است.",
