('hogwarts-legacy-deluxe-edition', $j${
  "intro": "Hogwarts Legacy Deluxe Edition نسخه ویژه نقش‌آفرینی اکشن جهان‌باز Hogwarts Legacy است که استودیو Avalanche Software ساخته و Warner Bros. Games در فوریه ۲۰۲۳ منتشر کرد. این بازی شما را به دنیای جادوگری کتاب‌های هری پاتر، اما حدود یک قرن پیش از تولد او، یعنی دهه ۱۸۰۰ میلادی، می‌برد. نسخه Deluxe علاوه بر بازی اصلی، بسته Dark Arts را هم دارد.",
