('raging-loop', $j${
  "intro": "Raging Loop یک رمان بصری با حال‌وهوای وحشت روانشناختی است که Kemco با همکاری Dwango منتشر کرده است. بازی ابتدا در سال ۲۰۱۵ در ژاپن عرضه شد و بعدها نسخه انگلیسی آن به کنسول‌ها رسید. داستان در روستای دورافتاده و مه‌گرفته یاسومیزو می‌گذرد؛ جایی که مه غلیظ اجازه خروج به هیچ‌کس نمی‌دهد و به گفته اهالی، خدایان باستانی برگشته‌اند تا روستاییان را یکی‌یکی شکار کنند.",
  "suits": ["علاقه‌مندان رمان بصری", "طرفداران معما و وحشت روانشناختی", "خوانندگان داستان‌های طولانی"],
