('octopath-traveler-0', $j${
  "intro": "Octopath Traveler 0 پیش‌درآمد سری نقش‌آفرینی محبوب Octopath Traveler است که Square Enix با همکاری استودیو Dokidoki Grooveworks ساخته و در دسامبر ۲۰۲۵ منتشر کرده است. بازی با همان سبک بصری HD-2D مشهور سری، یعنی ترکیب شخصیت‌های پیکسلی با محیط‌های سه‌بعدی پرنور، شما را به سرزمین اورسترا برمی‌گرداند. برای اولین بار در سری، می‌توانید قهرمان داستان را خودتان بسازید و زادگاه ویران‌شده‌اش را دوباره آباد کنید.",
