('tchia', $j${
  "intro": "Tchia یک ماجرای جهان‌باز استوایی است که استودیو Awaceb ساخته و Kepler Interactive در مارس ۲۰۲۳ منتشر کرده است. بازی از کالدونیای جدید، مجمع‌الجزایری در اقیانوس آرام که سازندگانش اهل آن‌جا هستند، الهام گرفته است. بالا بروید، با بال پرواز کنید، شنا کنید و با قایق خود در میان جزیره‌های زیبا سفر کنید؛ آن هم در دنیایی که بر پایه فیزیک ساخته شده و آزادی زیادی به شما می‌دهد.",
