('warhammer-40000-mechanicus-ii', $j${
  "intro": "Warhammer 40,000 Mechanicus II دنباله بازی استراتژی تاکتیکی تحسین‌شده Warhammer 40,000: Mechanicus است که استودیو Bulwark Studios ساخته و Kasedo Games در مه ۲۰۲۶ منتشر کرده است. این بازی نبردهای تاکتیکی سریع را با مدیریت استراتژیک ترکیب می‌کند و برای اولین بار به شما اجازه می‌دهد کنترل یکی از دو طرف درگیری را به دست بگیرید: لژیون‌های باستانی و نامیرای نکران‌ها یا پیروان دینی-فناورانه امنیسیا در آدپتوس مکانیکوس.",
